const primary = '#5146e5';

type Tone = 'violet' | 'coral' | 'teal' | 'amber' | 'green' | 'blue';

function Brand({ compact = false }: { compact?: boolean }) {
  return <Link href="/" className={`brand ${compact ? 'brand-compact' : ''}`}><span className="brand-mark"><Sparkles size={16} strokeWidth={2.6} /><GraduationCap size={17} /></span><span><strong>LearnAI</strong>{!compact && <small>Adaptive learning</small>}</span></Link>;
}

function IconButton({ label, children, onClick, className = '' }: { label: string; children: ReactNode; onClick?: () => void; className?: string }) {
  return <button className={`icon-button ${className}`} aria-label={label} title={label} onClick={onClick}>{children}</button>;
}

function Button({ children, variant = 'primary', href, onClick, type = 'button', className = '', icon, disabled = false }: { children: ReactNode; variant?: 'primary' | 'soft' | 'ghost' | 'outline' | 'dark'; href?: string; onClick?: () => void; type?: 'button' | 'submit'; className?: string; icon?: ReactNode; disabled?: boolean }) {
  const content = <>{children}{icon}</>;
  const classes = `button button-${variant} ${className}`;
  if (href) return <Link href={href} className={classes}>{content}</Link>;
  return <button type={type} className={classes} onClick={onClick} disabled={disabled}>{content}</button>;
}

function Badge({ children, tone = 'violet', dot = false }: { children: ReactNode; tone?: Tone | 'neutral'; dot?: boolean }) {
  return <span className={`badge badge-${tone}`}>{dot && <i className="badge-dot" />}{children}</span>;
}

function ProgressBar({ value, tone = 'violet', height = 'sm' }: { value: number; tone?: Tone; height?: 'sm' | 'md' }) {
  return <div className={`progress-track progress-${height}`}><span className={`progress-fill fill-${tone}`} style={{ width: `${value}%` }} /></div>;
}

function AIChip({ children = 'AI insight' }: { children?: ReactNode }) {
  return <span className="ai-chip"><Sparkles size={13} />{children}</span>;
}

function PageHeader({ eyebrow, title, subtitle, actions }: { eyebrow?: string; title: string; subtitle?: string; actions?: ReactNode }) {
  return <div className="page-header"><div><div className="eyebrow">{eyebrow || 'Your learning workspace'}</div><h1>{title}</h1>{subtitle && <p>{subtitle}</p>}</div>{actions && <div className="header-actions">{actions}</div>}</div>;
}

function Card({ children, className = '', accent = false }: { children: ReactNode; className?: string; accent?: boolean }) {
  return <section className={`card ${accent ? 'card-accent' : ''} ${className}`}>{children}</section>;
}

function StatCard({ label, value, hint, icon, tone = 'violet', trend }: { label: string; value: string; hint?: string; icon: ReactNode; tone?: Tone; trend?: string }) {
  return <Card className="stat-card"><div className={`stat-icon stat-${tone}`}>{icon}</div><div className="stat-copy"><span>{label}</span><strong>{value}</strong><small>{trend ? <em className="trend-up">{trend}</em> : hint}</small></div></Card>;
}

