  '/review-center': { eyebrow: 'Spaced repetition', title: 'Review center', subtitle: 'Bring the right concepts back at the right time before knowledge fades.', accent: 'amber', items: [{ title: 'HashMap fundamentals', detail: 'Original mastery 82% · current mastery 48% · last reviewed 14 days ago.', value: 48, meta: 'Due today' }, { title: 'SQL joins', detail: 'Last reviewed 8 days ago. One short retrieval set will keep it fresh.', value: 67, meta: 'Due today' }, { title: 'Method overriding', detail: 'Strong retention signal from your recent practice.', value: 78, meta: 'Upcoming · 3 days' }] },
