  '/skill-gap': { eyebrow: 'Goal alignment', title: 'Skill gap analysis', subtitle: 'Compare your current signal with the skills required for the role you want next.', accent: 'blue', items: [{ title: 'Java Developer', detail: 'Selected target · 5 skills mapped to your learning path.', value: 62, meta: 'Overall readiness' }, { title: 'Core Java & OOP', detail: 'Your strongest cluster, with a clear route into production patterns.', value: 82, meta: 'On track' }, { title: 'Spring Boot & REST API', detail: 'The largest gap between your current mastery and target readiness.', value: 38, meta: 'Priority gap' }] },
  '/ai-study-tools': { eyebrow: 'AI study studio', title: 'Study tools that do the busywork', subtitle: 'Turn any lesson into a summary, quiz, flashcards, or a focused explanation.', accent: 'violet', items: [{ title: 'Summarize a lesson', detail: 'Get the key ideas and exam-ready takeaways in seconds.', value: 0, meta: 'Generate summary' }, { title: 'Generate flashcards', detail: 'Create retrieval practice from your current topic and difficulty.', value: 0, meta: 'Create cards' }, { title: 'Document to quiz', detail: 'Upload a PDF, PPT, DOC, or TXT file and turn it into a learning set.', value: 0, meta: 'Upload document' }] },
  '/goals': { eyebrow: 'Momentum and milestones', title: 'Your learning goals', subtitle: 'Keep the destination visible while LearnAI adapts the route underneath it.', accent: 'green', items: [{ title: 'Become a Java Developer', detail: 'Target date · 18 December 2026 · 5 milestones mapped.', value: 62, meta: '62% complete' }, { title: 'Daily target', detail: '30 minutes or 10 questions keeps your current pace healthy.', value: 72, meta: '4 of 5 days this week' }, { title: 'Next milestone', detail: 'Complete the Collections adaptive check and unlock Spring basics.', value: 0, meta: 'Due this week' }] },
