function AdaptiveFeaturePage({ config, admin = false }: { config: (typeof featureConfigs)[string]; admin?: boolean }) {
  const [active, setActive] = useState(0);
  const [started, setStarted] = useState(false);
  const Shell = admin ? AdminLayout : AppShell;
  return <Shell><PageHeader eyebrow={config.eyebrow} title={config.title} subtitle={config.subtitle} actions={<Button onClick={() => setStarted(true)} icon={<Sparkles size={15} />}>{started ? 'Signal updated' : 'Ask LearnAI'}</Button>} /><div className="recommendation-banner"><div className="banner-icon"><Sparkles size={20} /></div><div><AIChip>Explainable signal</AIChip><h3>{started ? 'Your next step has been recalibrated.' : 'Small, focused steps compound.'}</h3><p>{started ? 'The mock learner model used your selected focus to adjust the recommendation below.' : 'Every card shows the evidence behind the recommendation, not just a score.'}</p></div><div className="banner-stat"><b>{config.items.length}</b><span>next best<br />actions</span></div></div><div className="rec-grid feature-route-grid">{config.items.map((item, index) => <Card key={item.title} className={`recommendation-card ${active === index ? 'recommendation-active' : ''}`}><div className="rec-top"><span className={`rec-icon rec-${config.accent}`}><Sparkles size={16} /></span><Badge tone={config.accent}>{item.meta}</Badge></div><h3>{item.title}</h3><p>{item.detail}</p>{item.value > 0 && <><div className="rec-progress-label"><span>Mastery signal</span><b>{item.value}%</b></div><ProgressBar value={item.value} tone={config.accent} /></>}<div className="why-box"><b>Why this matters</b><span><Check size={14} />Based on your current learner model</span><span><Check size={14} />Prioritized for your selected goal</span></div><Button variant={active === index ? 'primary' : 'soft'} onClick={() => { setActive(index); setStarted(true); }} icon={<ArrowRight size={15} />}>{active === index ? 'Focused now' : item.meta}</Button></Card>)}</div><Card className="transparency-card"><AIChip>How LearnAI works</AIChip><div className="transparency-flow"><span>Learner data</span><ArrowRight size={15} /><span>Learner model</span><ArrowRight size={15} /><span>Recommendation engine</span><ArrowRight size={15} /><span>Adaptive learning</span></div><p>AI-generated content may occasionally contain errors. Verify important academic information with course materials.</p></Card></Shell>;
}

function Onboarding() { const [, navigate] = useLocation(); const [step, setStep] = useState(0); const [selected, setSelected] = useState('Placement preparation'); const steps = [{ title: 'What are you learning for?', options: ['Placement preparation', 'Academic improvement', 'Certification', 'Skill development'] }, { title: 'Where are you starting?', options: ['Beginner', 'Intermediate', 'Advanced'] }, { title: 'Choose your interests', options: ['Java', 'Python', 'SQL', 'React', 'Spring Boot', 'DSA'] }, { title: 'How much time do you have?', options: ['15 min', '30 min', '1 hour', '2 hours'] }]; const current = steps[step]; return <div className="auth-page onboarding-page"><div className="auth-form-wrap"><div className="auth-form"><Brand /><div className="auth-heading"><div className="eyebrow">AI onboarding · {step + 1} of {steps.length}</div><h2>Let’s understand how you learn.</h2><p>{current.title}</p></div><div className="onboarding-progress">{steps.map((_, index) => <span key={index} className={index <= step ? 'active' : ''} />)}</div><div className="choice-grid onboarding-choices">{current.options.map((option) => <button type="button" key={option} className={selected === option ? 'choice-selected' : ''} onClick={() => setSelected(option)}><span>{['✦', '◎', '◈', '↗', '✚', '⌁'][steps[step].options.indexOf(option)]}</span><b>{option}</b><small>{step === 0 ? 'LearnAI will shape your path around this goal.' : 'Used to calibrate your first learning path.'}</small></button>)}</div><div className="onboarding-actions"><Button variant="ghost" onClick={() => setStep(Math.max(0, step - 1))} disabled={step === 0}>Back</Button><Button onClick={() => step === steps.length - 1 ? navigate('/assessment') : setStep(step + 1)} icon={<ArrowRight size={16} />}>{step === steps.length - 1 ? 'Start skill assessment' : 'Continue'}</Button></div></div></div><div className="register-side"><Brand /><div className="register-quote"><span>“</span><h2>A better path starts with a better signal.</h2><p>LearnAI uses your goals, confidence, and study rhythm to personalize what comes next.</p></div></div></div>; }

function ForgotPassword() { const [sent, setSent] = useState(false); return <div className="auth-page"><div className="auth-form-wrap"><div className="auth-form"><Link href="/login" className="auth-back"><ArrowLeft size={15} />Back to sign in</Link><div className="auth-heading"><div className="eyebrow">Account recovery</div><h2>Reset your password.</h2><p>{sent ? 'Check your inbox for a secure reset link.' : 'Enter your email and we’ll send a mock recovery link.'}</p></div>{sent ? <Card className="empty-state-card"><Check size={22} /><h3>Recovery link sent</h3><p>For this frontend demo, the reset flow is simulated.</p><Button href="/login">Return to sign in</Button></Card> : <form onSubmit={(event) => { event.preventDefault(); setSent(true); }}><label>Email address<input type="email" defaultValue={student.email} required /></label><Button type="submit" className="auth-submit">Send reset link <ArrowRight size={16} /></Button></form>}</div></div></div>; }

function AdminLayout({ children }: { children: ReactNode }) { const { user } = useAuth(); const [, navigate] = useLocation(); useEffect(() => { if (!user) navigate('/login'); else if (user.role !== 'admin') navigate('/dashboard'); }, [user, navigate]); if (!user || user.role !== 'admin') return null; return <AppShell admin>{children}</AppShell>; }
function AdminDashboard() { return <AdminLayout><PageHeader eyebrow="LearnAI operations" title="Good morning, admin." subtitle="A concise view of learner health and content performance." actions={<Button variant="soft" icon={<RefreshCw size={15} />}>Refresh data</Button>} /><div className="stats-grid admin-stats">{adminStats.map((stat, index) => <StatCard key={stat.label} label={stat.label} value={stat.value} trend={stat.trend} icon={index === 0 ? <Users size={18} /> : index === 1 ? <Library size={18} /> : index === 2 ? <BookOpen size={18} /> : <FileQuestion size={18} />} tone={['violet', 'teal', 'amber', 'coral'][index] as Tone} />)}</div><div className="admin-dashboard-grid"><Card className="chart-card admin-chart"><div className="card-heading"><div><div className="eyebrow">Engagement overview</div><h2>Student activity</h2></div><Badge tone="green" dot>Live</Badge></div><ResponsiveContainer width="100%" height={270}><AreaChart data={[{ month: 'Apr', students: 1200, completion: 46 }, { month: 'May', students: 1480, completion: 52 }, { month: 'Jun', students: 1740, completion: 58 }, { month: 'Jul', students: 1920, completion: 61 }, { month: 'Aug', students: 2280, completion: 69 }, { month: 'Sep', students: 2481, completion: 74 }]}><defs><linearGradient id="studentGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#5146e5" stopOpacity=".22" /><stop offset="100%" stopColor="#5146e5" stopOpacity="0" /></linearGradient></defs><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="var(--border)" /><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{ fill: 'var(--muted)', fontSize: 12 }} /><YAxis axisLine={false} tickLine={false} tick={{ fill: 'var(--muted)', fontSize: 12 }} /><Tooltip contentStyle={{ background: 'var(--surface-strong)', border: '1px solid var(--border)', borderRadius: 12 }} /><Area type="monotone" dataKey="students" stroke="#5146e5" strokeWidth={3} fill="url(#studentGradient)" /></AreaChart></ResponsiveContainer></Card><Card className="admin-health"><div className="card-heading"><div><div className="eyebrow">Learning health</div><h2>Course completion</h2></div><MoreHorizontal size={18} /></div><div className="health-ring"><span><b>74%</b><small>avg. completion</small></span><svg viewBox="0 0 42 42"><circle className="circle-bg" cx="21" cy="21" r="16" /><circle className="circle-value" cx="21" cy="21" r="16" strokeDasharray="74 26" /></svg></div><div className="health-rows"><span><i className="legend-dot violet" />Completed <b>1,842</b></span><span><i className="legend-dot blush" />In progress <b>512</b></span><span><i className="legend-dot gray" />Not started <b>127</b></span></div></Card><Card className="difficult-topics"><div className="card-heading"><div><div className="eyebrow">Model feedback</div><h2>Most difficult topics</h2></div><Link href="/admin/questions" className="text-link">Question bank <ArrowRight size={14} /></Link></div>{[{ label: 'Java Collections', value: 42 }, { label: 'SQL Joins', value: 38 }, { label: 'Polymorphism', value: 31 }, { label: 'Spring Security', value: 27 }].map((item) => <div className="difficulty-row" key={item.label}><span>{item.label}</span><ProgressBar value={item.value} tone="coral" /><b>{item.value}%</b></div>)}</Card></div><div className="admin-bottom-grid"><Card><div className="card-heading"><div><div className="eyebrow">Recent signal</div><h2>Active learners</h2></div><Link href="/admin/students" className="text-link">View all <ArrowRight size={14} /></Link></div><div className="admin-learner-list">{adminStudents.slice(0, 4).map((item) => <div key={item.email}><span className="admin-person-avatar">{item.name.split(' ').map((n) => n[0]).join('')}</span><div><b>{item.name}</b><small>{item.course}</small></div><span className="learner-mastery">{item.mastery}%</span><Badge tone={item.status === 'Active' ? 'green' : item.status === 'At risk' ? 'amber' : 'neutral'} dot>{item.status}</Badge></div>)}</div></Card><Card className="admin-ai-card"><div className="admin-ai-graphic"><Sparkles size={24} /></div><AIChip>Content opportunity</AIChip><h3>HashMap is a shared friction point.</h3><p>8% of active learners repeat the same key-value operation error. A focused explainer could unlock the whole Collections module.</p><Button href="/admin/questions" variant="dark" icon={<WandSparkles size={15} />}>Generate content</Button></Card></div></AdminLayout>; }

function AdminCourses() { const [modal, setModal] = useState(false); return <AdminLayout><PageHeader eyebrow="Content studio" title="Course management" subtitle="Shape the library your learners rely on." actions={<Button onClick={() => setModal(true)} icon={<Plus size={16} />}>Create course</Button>} /><div className="admin-toolbar"><div className="search-field"><Search size={17} /><input placeholder="Search courses..." /></div><Button variant="outline" icon={<ListFilter size={15} />}>Filters</Button></div><div className="admin-course-table"><div className="table-head"><span>Course</span><span>Category</span><span>Lessons</span><span>Students</span><span>Completion</span><span>Actions</span></div>{courses.slice(0, 5).map((course) => <div className="table-row" key={course.id}><div className="table-course"><span className="table-course-icon" style={{ background: course.accent, color: course.color }}>{course.icon}</span><div><b>{course.title}</b><small>Updated 2 days ago</small></div></div><span><Badge tone="neutral">{course.category}</Badge></span><span>{course.lessons}</span><span>{course.learners}</span><span><div className="table-progress"><ProgressBar value={course.progress || 62} tone="violet" /><b>{course.progress || 62}%</b></div></span><span className="table-actions"><IconButton label="Edit course"><Settings2 size={15} /></IconButton><IconButton label="More options"><MoreHorizontal size={16} /></IconButton></span></div>)}</div>{modal && <Modal title="Create a course" onClose={() => setModal(false)}><div className="modal-form"><label>Course title<input placeholder="e.g. Data Structures in Java" /></label><label>Description<textarea placeholder="What will learners be able to do?" /></label><div className="field-grid"><label>Category<select><option>Programming</option><option>Database</option><option>Web Development</option></select></label><label>Difficulty<select><option>Beginner</option><option>Intermediate</option><option>Advanced</option></select></label></div><div className="modal-actions"><Button variant="outline" onClick={() => setModal(false)}>Cancel</Button><Button onClick={() => setModal(false)} icon={<Check size={15} />}>Create course</Button></div></div></Modal>}</AdminLayout>; }

function AdminCourseEditor({ newCourse = false }: { newCourse?: boolean }) { const [saved, setSaved] = useState(false); const course = courses[0]; return <AdminLayout><PageHeader eyebrow="Course studio" title={newCourse ? 'Create a course' : `Edit ${course.title}`} subtitle="Build the progression from prerequisites to real-world application." actions={<Button onClick={() => setSaved(true)} icon={<Check size={15} />}>{saved ? 'Saved as draft' : 'Save draft'}</Button>} /><div className="two-col"><Card><div className="card-heading"><div><div className="eyebrow">Course details</div><h2>Define the learning promise</h2></div><Badge tone="violet">Draft</Badge></div><div className="modal-form"><label>Course title<input defaultValue={newCourse ? '' : course.title} placeholder="e.g. Data Structures & Algorithms" /></label><label>Description<textarea defaultValue={newCourse ? '' : course.description} /></label><div className="field-grid"><label>Category<select defaultValue={course.category}><option>Programming</option><option>Database</option><option>Web Development</option><option>AI / ML</option></select></label><label>Difficulty<select defaultValue={course.difficulty}><option>Beginner</option><option>Intermediate</option><option>Advanced</option></select></label></div><label>Learning outcomes<textarea defaultValue="Build confidence through foundations, targeted practice, adaptive assessments, and a project that mirrors real work." /></label></div></Card><Card><div className="card-heading"><div><div className="eyebrow">Curriculum structure</div><h2>Progression map</h2></div><Button variant="soft" icon={<Plus size={15} />}>Add module</Button></div><div className="module-list admin-module-list">{['Beginner · Foundations', 'Intermediate · Core concepts', 'Advanced · Applied patterns', 'Project · Real-world application'].map((item, index) => <div className="module-row" key={item}><span className="module-index">{String(index + 1).padStart(2, '0')}</span><div><b>{item}</b><small>{index === 0 ? 'Prerequisites and baseline lessons' : index === 3 ? 'Capstone assessment and project' : 'Topics, lessons, practice, and assessment'}</small></div><ChevronRight size={16} /></div>)}</div><div className="modal-ai-intro"><Sparkles size={17} /><p>AI can suggest lesson sequencing after you define the prerequisite relationships.</p></div></Card></div></AdminLayout>; }

function Modal({ title, children, onClose }: { title: string; children: ReactNode; onClose: () => void }) { return <div className="modal-backdrop" onClick={onClose}><div className="modal" onClick={(event) => event.stopPropagation()}><div className="modal-head"><h2>{title}</h2><IconButton label="Close modal" onClick={onClose}><X size={17} /></IconButton></div>{children}</div></div>; }

function AdminQuestions() { const [modal, setModal] = useState(false); const [generated, setGenerated] = useState(false); return <AdminLayout><PageHeader eyebrow="Content studio" title="Question bank" subtitle="Create assessments that reveal understanding, not just recall." actions={<Button onClick={() => setModal(true)} icon={<WandSparkles size={16} />}>Generate with AI</Button>} /><div className="admin-toolbar"><div className="search-field"><Search size={17} /><input placeholder="Search questions, topics..." /></div><div className="filter-chips"><Badge tone="neutral">All topics <ChevronDown size={12} /></Badge><Badge tone="neutral">All difficulty <ChevronDown size={12} /></Badge><Badge tone="neutral">All types <ChevronDown size={12} /></Badge></div></div><div className="table-card"><div className="table-head question-head"><span>Question</span><span>Topic</span><span>Difficulty</span><span>Type</span><span>Usage</span><span>Actions</span></div>{adminQuestions.map((item) => <div className="table-row question-row" key={item.question}><div><b>{item.question}</b><small>Updated 4 hours ago</small></div><span>{item.topic}</span><span><Badge tone={item.difficulty === 'Hard' ? 'coral' : item.difficulty === 'Easy' ? 'teal' : 'violet'}>{item.difficulty}</Badge></span><span>{item.type}</span><span>{item.usage}×</span><span className="table-actions"><IconButton label="Edit question"><Settings2 size={15} /></IconButton><IconButton label="More options"><MoreHorizontal size={16} /></IconButton></span></div>)}</div>{generated && <Card className="generated-questions"><div className="generated-head"><AIChip>Generated just now</AIChip><button onClick={() => setGenerated(false)}><X size={15} /></button></div><h3>3 questions ready for review</h3><p>HashMap · Intermediate · Multiple choice</p><div className="generated-list"><span>01 · When would you choose a HashMap over a TreeMap?</span><span>02 · Which contract must custom keys satisfy?</span><span>03 · Predict the output of this lookup sequence.</span></div><Button variant="soft" onClick={() => setGenerated(false)}>Review questions <ArrowRight size={15} /></Button></Card>}{modal && <Modal title="Generate questions with AI" onClose={() => setModal(false)}><div className="modal-form"><div className="modal-ai-intro"><Sparkles size={17} /><p>Describe the signal you want to explore. You’ll be able to review and edit before publishing.</p></div><label>Topic<input defaultValue="Java Collections" /></label><div className="field-grid"><label>Difficulty<select><option>Intermediate</option><option>Beginner</option><option>Advanced</option></select></label><label>Number of questions<select><option>3</option><option>5</option><option>10</option></select></label></div><label>Question type<select><option>Multiple choice</option><option>Short answer</option><option>Code challenge</option></select></label><div className="modal-actions"><Button variant="outline" onClick={() => setModal(false)}>Cancel</Button><Button onClick={() => { setModal(false); setGenerated(true); }} icon={<Sparkles size={15} />}>Generate questions</Button></div></div></Modal>}</AdminLayout>; }

function AdminStudents() { return <AdminLayout><PageHeader eyebrow="Learner health" title="Students" subtitle="Understand who is moving, who is stuck, and where to intervene." actions={<Button variant="soft" icon={<ArrowRight size={15} />}>Export report</Button>} /><div className="student-summary"><div><Users size={18} /><b>2,481</b><span>total students</span></div><div><Activity size={18} /><b>1,842</b><span>active this month</span></div><div><TrendingUp size={18} /><b>74%</b><span>avg. completion</span></div><div><CircleHelp size={18} /><b>12%</b><span>need attention</span></div></div><div className="table-card student-table"><div className="table-head student-head"><span>Student</span><span>Course</span><span>Mastery</span><span>Progress</span><span>Last active</span><span>Status</span></div>{adminStudents.map((item) => <div className="table-row student-row" key={item.email}><div className="table-person"><span className="admin-person-avatar">{item.name.split(' ').map((n) => n[0]).join('')}</span><div><b>{item.name}</b><small>{item.email}</small></div></div><span>{item.course}</span><span><b className="mastery-table-value">{item.mastery}%</b></span><span><div className="table-progress"><ProgressBar value={item.progress} tone="violet" /><b>{item.progress}%</b></div></span><span>{item.active}</span><span><Badge tone={item.status === 'Active' ? 'green' : item.status === 'At risk' ? 'amber' : 'neutral'} dot>{item.status}</Badge></span></div>)}</div></AdminLayout>; }

function Login() { const [, navigate] = useLocation(); const { login } = useAuth(); const [email, setEmail] = useState('ranganayaki.ks@learnai.dev'); const [password, setPassword] = useState('learnai'); return <div className="auth-page"><div className="auth-side"><div className="auth-side-inner"><Brand /><div className="auth-promise"><AIChip>Learning that adapts</AIChip><h1>Your curiosity deserves a better path.</h1><p>LearnAI turns your patterns into progress with a learning experience that moves at your pace.</p><div className="auth-signal"><div className="signal-line"><span /><span /><span /><span /><span /><span /><span /></div><div><b>+24%</b><small>mastery growth in 6 weeks</small></div></div></div><span className="auth-footer">Adaptive learning. Personalized growth.</span></div></div><div className="auth-form-wrap"><div className="auth-form"><Link href="/" className="auth-back"><ArrowLeft size={15} />Back to home</Link><div className="auth-heading"><div className="eyebrow">Welcome back</div><h2>Sign in to your learning space.</h2><p>Pick up exactly where you left off.</p></div><form onSubmit={(event) => { event.preventDefault(); login(email); navigate('/dashboard'); }}><label>Email address<input type="email" value={email} onChange={(event) => setEmail(event.target.value)} required /></label><label>Password<div className="password-field"><input type="password" value={password} onChange={(event) => setPassword(event.target.value)} required /><button type="button">Show</button></div></label><div className="form-row"><label className="checkbox-label"><input type="checkbox" defaultChecked />Remember me</label><a href="#forgot">Forgot password?</a></div><Button type="submit" className="auth-submit">Sign in <ArrowRight size={16} /></Button></form><div className="auth-divider"><span>or continue with</span></div><Button variant="outline" className="google-button"><span className="google-g">G</span>Continue with Google</Button><p className="auth-switch">Don’t have an account? <Link href="/register">Create one</Link></p></div></div></div>; }

function Register() { const [, navigate] = useLocation(); const { register } = useAuth(); const [name, setName] = useState('Ranganayaki KS'); const [email, setEmail] = useState('ranganayaki.ks@learnai.dev'); return <div className="auth-page register-page"><div className="auth-form-wrap"><div className="auth-form register-form"><Link href="/" className="auth-back"><ArrowLeft size={15} />Back to home</Link><div className="auth-heading"><div className="eyebrow">Start with a signal</div><h2>Build a learning path that feels like yours.</h2><p>Tell us a little about where you’re going. You can change this later.</p></div><div className="onboarding-progress"><span className="active" /><span /><span /><small>1 of 3</small></div><form onSubmit={(event) => { event.preventDefault(); register(name, email); navigate('/onboarding'); }}><div className="field-grid"><label>Full name<input value={name} onChange={(event) => setName(event.target.value)} required /></label><label>Email address<input type="email" value={email} onChange={(event) => setEmail(event.target.value)} required /></label></div><label>What are you learning for?<select defaultValue="Build production-ready projects"><option>Build production-ready projects</option><option>Prepare for interviews</option><option>Pass my final-year project</option><option>Explore a new field</option></select></label><label>Current skill level<div className="choice-grid">{['Beginner', 'Intermediate', 'Advanced'].map((item, index) => <button type="button" className={index === 1 ? 'choice-selected' : ''} key={item}><span>{['✦', '◎', '◈'][index]}</span><b>{item}</b><small>{['I’m starting out', 'I know the basics', 'I’m going deeper'][index]}</small></button>)}</div></label><label>How much time can you give each day?<div className="goal-options"><button type="button">30 min</button><button type="button" className="selected">1–2 hours</button><button type="button">2+ hours</button></div></label><Button type="submit" className="auth-submit">Create my learning space <ArrowRight size={16} /></Button></form><p className="auth-switch">Already have an account? <Link href="/login">Sign in</Link></p></div></div><div className="register-side"><Brand /><div className="register-quote"><span>“</span><h2>The best learning plan is the one you’ll actually want to return to.</h2><p>LearnAI makes progress visible, so momentum feels natural.</p></div><div className="register-insight"><span className="note-icon note-violet"><Sparkles size={15} /></span><span><b>Your path is yours</b><small>Goals and signals shape every recommendation.</small></span></div></div></div>; }

function NotFound() { return <div className="empty-page"><Brand /><div><h1>That page took a wrong turn.</h1><p>Let’s get you back to your learning space.</p><Button href="/dashboard" icon={<ArrowRight size={16} />}>Back to dashboard</Button></div></div>; }

function FeatureRoute({ path }: { path: string }) { const config = featureConfigs[path]; return <AdaptiveFeaturePage config={config} admin={path.startsWith('/admin')} />; }

function AppRoutes() {
  return <Switch>
    <Route path="/" component={Landing} /><Route path="/login" component={Login} /><Route path="/register" component={Register} /><Route path="/forgot-password" component={ForgotPassword} /><Route path="/onboarding" component={Onboarding} />
    <Route path="/dashboard" component={Dashboard} /><Route path="/courses" component={Courses} /><Route path="/courses/:id" component={CourseDetails} /><Route path="/learn/:lessonId" component={LessonPage} /><Route path="/learning-path"><FeatureRoute path="/learning-path" /></Route><Route path="/assessment" component={Assessment} /><Route path="/assessment/:assessmentId/result" component={QuizResult} /><Route path="/assessment/:assessmentId" component={Quiz} /><Route path="/adaptive-practice"><FeatureRoute path="/adaptive-practice" /></Route><Route path="/recommendations" component={Recommendations} /><Route path="/review-center"><FeatureRoute path="/review-center" /></Route><Route path="/knowledge-map"><FeatureRoute path="/knowledge-map" /></Route><Route path="/analytics" component={Analytics} /><Route path="/skill-gap"><FeatureRoute path="/skill-gap" /></Route><Route path="/ai-tutor" component={AITutor} /><Route path="/study-plan" component={StudyPlan} /><Route path="/flashcards" component={Flashcards} /><Route path="/ai-study-tools"><FeatureRoute path="/ai-study-tools" /></Route><Route path="/interview"><FeatureRoute path="/interview" /></Route><Route path="/goals"><FeatureRoute path="/goals" /></Route><Route path="/profile" component={Profile} />
    <Route path="/admin" component={AdminDashboard} /><Route path="/admin/courses" component={AdminCourses} /><Route path="/admin/courses/new"><AdminCourseEditor newCourse /></Route><Route path="/admin/courses/:courseId"><AdminCourseEditor /></Route><Route path="/admin/questions" component={AdminQuestions} /><Route path="/admin/students" component={AdminStudents} /><Route path="/admin/analytics"><FeatureRoute path="/admin/analytics" /></Route><Route path="/admin/ai-content"><FeatureRoute path="/admin/ai-content" /></Route><Route component={NotFound} />
  </Switch>;
}

export default function App() { return <AuthProvider><AppRoutes /></AuthProvider>; }
